#!/usr/bin/env python3
"""Measure original O_INIT header carriers and bind its unchanged native bridge."""
import hashlib,json,os,re,shlex,subprocess,tempfile
from pathlib import Path
root=Path(__file__).resolve().parents[1];ref=Path(os.environ.get('STANDALONE_REFERENCE_ROOT',root)).resolve();tree=ref/'.cache/wasm64-build/tree';clang=ref/'.cache/emsdk/upstream/bin/clang';header=root/'scripts/tu-o_init-layout.h';nativefile=root/'nethack-c/wasm/tu-support.c';native=nativefile.read_text();lib=root/'nethack-c/wasm/tu-libraries/o_init.js';layout=json.loads((root/'js/wasm/tu-layouts.json').read_text())['o_init'];public=json.loads((root/'js/standalone/public-functions.json').read_text())['functions']
flags=['--target=wasm64-unknown-emscripten','--sysroot='+str(ref/'.cache/emsdk/upstream/emscripten/cache/sysroot'),'-include',str(root/'nethack-c/wasm/native-terminal.h'),'-I'+str(tree/'include'),'-I'+str(ref/'.cache/ncurses-wasm64-build/include'),*['-D'+v for v in json.loads((root/'nethack-c/wasm/compile-defines.json').read_text())]]
with tempfile.TemporaryDirectory(prefix='discoveries-abi-')as d:
 p=Path(d)/'p.c';body='#include '+json.dumps(str(header))+'\n';p.write_text(body);cpp=subprocess.check_output([str(clang),*flags,'-E','-P',str(p)],text=True);table=re.search(r'o_init_layout\[\]\s*=\s*\{(.*?)\n\};',cpp,re.S)[1];rows=re.findall(r'\{\s*"([^"]+)"\s*,\s*(.*?)\s*\}',table,re.S);p.write_text(body+'\n'.join('const unsigned long p'+str(i)+'='+('('+e+')'if e else'0')+';'for i,(_,e)in enumerate(rows)));ir=subprocess.check_output([str(clang),*flags,'-S','-emit-llvm','-O0','-o','-',str(p)],text=True);measured={n:int(re.search(r'@p'+str(i)+r' = .*?constant i64 (-?\d+)',ir)[1])&((1<<64)-1)for i,(n,_)in enumerate(rows)}
 measured['size']=measured['objectClassSize']
 expected={k:v for k,v in layout.items()if k!='strings'};assert set(measured)==set(expected)and all(v==(int(expected[k])&((1<<64)-1))for k,v in measured.items()),repr({'missing':set(expected)-set(measured),'extra':set(measured)-set(expected),'different':[(k,v,expected.get(k))for k,v in measured.items()if k in expected and v!=(int(expected[k])&((1<<64)-1))]})
 deps=subprocess.check_output([str(clang),*flags,'-M',str(p)],text=True);headers=[Path(v).resolve()for v in shlex.split(deps.split(':',1)[1].replace('\\\n',''))if Path(v).resolve().is_relative_to(ref)]
names=re.findall(r'^export function (\w+)',(root/'js/ported/o_init.js').read_text(),re.M);dependencies=sorted(set(re.findall(r'\b_([A-Za-z]\w*)\(',lib.read_text())));dependencies=[n for n in dependencies if not n.startswith('teleport_')];assert all(n in public for n in dependencies),[n for n in dependencies if n not in public]
source=(tree/'src/o_init.c').read_text();assertion=source.index('assert(p != NULL)');strlen=re.search(r'Strlen\([^\n]*oc_uname[^\n]*\)',source);assert strlen
inputs=[Path(__file__).resolve(),root/'js/standalone/discoveries.js',root/'js/standalone/object-state.js',header,nativefile,lib,root/'js/ported/o_init.js',root/'js/nethack/bindings/o_init.js',root/'js/standalone/records.json',root/'js/standalone/public-functions.json',root/'nethack-c/wasm/compile-defines.json'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
result={'layout':layout,'assertion':{'condition':'p != NULL','file':'o_init.c','line':source[:assertion].count('\n')+1,'function':'disco_output_sorted'},'strlenSite':{'line':source[:strlen.start()].count('\n')+1,'function':'savenames'},'dependencies':{n:public[n]for n in dependencies},'public':{n:public[n]for n in names if n in public},'sourceSha256':{str(p.relative_to(root)):sha(p)for p in inputs},'referenceHeaderSha256':{str(p.relative_to(ref)):sha(p)for p in sorted(set(headers+[tree/'src/o_init.c']))}}
(root/'js/standalone/discoveries-abi.json').write_text(json.dumps(result,indent=2)+'\n');print('Bound original O_INIT native transport.')
